{
  "summary": "Concrete MIHVER V1C Privileged Authorization Ledger Architecture (decision-6) retaining V5 approved baseline while fixing the lost-ack retry idempotency blocker with durable privileged operation journaling and dual-layer CAS increment protocol.",
  "payload": {
    "decisionId": "decision-6",
    "architectureVersion": "V1C",
    "daemon": {
      "daemonName": "authledgerd",
      "osIdentity": "mihver-ledger",
      "storageEngine": "SQLite-WAL",
      "dbPath": "/var/lib/mihver/authledger/authledger.db",
      "adminPolicyPath": "/etc/mihver/authledger/admin_policy.json",
      "adminSocketPath": "/run/mihver/authledger/admin.sock",
      "clientSocketPath": "/run/mihver/authledger/client.sock",
      "privilegeSeparation": {
        "adminSocketPermissions": "0660 root:mihver-admin",
        "clientSocketPermissions": "0666 root:root",
        "socketFilesystemSemantics": "Reachability only; peer authentication uses kernel SO_PEERCRED UID.",
        "adminAuthorization": "SO_PEERCRED UID must match an exact integer UID in root-owned /etc/mihver/authledger/admin_policy.json (mode 0644/0600 root:root). Caller-provided identity strings or UIDs are rejected and never override kernel UID.",
        "policyIntegrityCheck": "authledgerd verifies admin_policy.json is owned by UID 0, GID 0, non-writable by group/other, and fails closed on any mismatch."
      }
    },
    "stopEpochDomain": {
      "type": "INTEGER",
      "min": 0,
      "max": 9007199254740991,
      "description": "JSON/JS/SQLite safe integer domain [0, 2^53 - 1]. No BigInt, no floats, no wraparound, no decrements or resets via API. Exceeding max fails closed with STOP_EPOCH_EXHAUSTED.",
      "schemaCheck": "CHECK(stop_epoch >= 0 AND stop_epoch <= 9007199254740991)"
    },
    "durableJournalSchema": {
      "tableName": "admin_operation_journal",
      "ddl": "CREATE TABLE IF NOT EXISTS admin_operation_journal (authenticated_peer_uid INTEGER NOT NULL, operation_kind TEXT NOT NULL, admin_operation_id TEXT NOT NULL, request_hash TEXT NOT NULL, result_code TEXT NOT NULL, result_stop_epoch INTEGER, created_at INTEGER NOT NULL, PRIMARY KEY (authenticated_peer_uid, operation_kind, admin_operation_id))",
      "requestHashBinding": {
        "domainSeparator": "MIHVER_V1C_ADMIN_OP_V1",
        "algorithm": "SHA-256",
        "canonicalInput": "domainSeparator || ':' || authenticatedPeerUid || ':' || operationKind || ':' || adminOperationId || ':' || expectedStopEpoch",
        "conflictBehavior": "If primary key matches but stored request_hash != current request_hash, fail closed with IDEMPOTENCY_KEY_REUSE immediately without mutating state or returning cached result."
      }
    },
    "incrementStopEpochProtocol": {
      "rpcName": "incrementStopEpoch",
      "parameters": {
        "adminOperationId": "Opaque bounded UUIDv4/hex string (36-64 chars) generated by client before first transmission.",
        "expectedStopEpoch": "Integer [0, 9007199254740991] representing caller's observed current global stopEpoch."
      },
      "executionSteps": [
        "1. Extract authenticatedPeerUid from stream socket via kernel SO_PEERCRED.",
        "2. Authorize authenticatedPeerUid against root-owned admin allowlist policy. Fail UNAUTHORIZED if not listed.",
        "3. Validate adminOperationId syntax and safe integer range of expectedStopEpoch. Fail INVALID_ARGUMENT on format violation.",
        "4. Compute canonical requestHash = SHA256('MIHVER_V1C_ADMIN_OP_V1:' || authenticatedPeerUid || ':INCREMENT_STOP_EPOCH:' || adminOperationId || ':' || expectedStopEpoch).",
        "5. BEGIN IMMEDIATE TRANSACTION on SQLite store.",
        "6. SELECT request_hash, result_code, result_stop_epoch FROM admin_operation_journal WHERE authenticated_peer_uid = ? AND operation_kind = 'INCREMENT_STOP_EPOCH' AND admin_operation_id = ?.",
        "7. IF row found: IF stored request_hash != computed requestHash -> ROLLBACK and return ERROR: IDEMPOTENCY_KEY_REUSE. ELSE -> COMMIT/ROLLBACK read-only and return cached response { resultCode: stored.result_code, stopEpoch: stored.result_stop_epoch, replayed: true } without mutating state.",
        "8. IF row NOT found: SELECT current_stop_epoch FROM global_epoch_register.",
        "9. IF expectedStopEpoch != current_stop_epoch -> ROLLBACK and return ERROR: STALE_EXPECTED_STOP_EPOCH (with current_stop_epoch).",
        "10. IF current_stop_epoch == 9007199254740991 -> ROLLBACK and return ERROR: STOP_EPOCH_EXHAUSTED.",
        "11. nextStopEpoch = current_stop_epoch + 1.",
        "12. UPDATE global_epoch_register SET current_stop_epoch = nextStopEpoch, updated_at = unix_timestamp_ms().",
        "13. INSERT INTO admin_operation_journal (authenticated_peer_uid, operation_kind, admin_operation_id, request_hash, result_code, result_stop_epoch, created_at) VALUES (?, 'INCREMENT_STOP_EPOCH', ?, ?, 'SUCCESS', nextStopEpoch, unix_timestamp_ms()).",
        "14. INSERT INTO audit_events (actor_uid, action, previous_epoch, new_epoch, operation_id, timestamp) VALUES (authenticatedPeerUid, 'INCREMENT_STOP_EPOCH', current_stop_epoch, nextStopEpoch, adminOperationId, unix_timestamp_ms()).",
        "15. COMMIT TRANSACTION.",
        "16. Return { resultCode: 'SUCCESS', stopEpoch: nextStopEpoch, replayed: false } to caller."
      ]
    },
    "lostAckTraces": {
      "traceA_RetriedWithSameOperationId": {
        "scenario": "Current stopEpoch = N. Caller sends adminOperationId = X with expectedStopEpoch = N. Daemon commits transaction updating stopEpoch N -> N+1, writing journal row (uid, 'INCREMENT_STOP_EPOCH', X, requestHash, 'SUCCESS', N+1). Acknowledgment is lost in network/pipe before reaching caller. Caller retries with same UID, adminOperationId = X, expectedStopEpoch = N.",
        "resolution": "Daemon extracts peer UID, computes identical requestHash, begins transaction, finds existing entry in admin_operation_journal for (UID, 'INCREMENT_STOP_EPOCH', X). Stored request_hash matches current requestHash. Daemon returns stored resultCode='SUCCESS' and stopEpoch=N+1 with replayed=true. No state mutation occurs; global stopEpoch remains N+1 and cannot advance to N+2."
      },
      "traceB_RetriedWithLostOperationIdAndNewId": {
        "scenario": "Current stopEpoch = N. Caller sends adminOperationId = X with expectedStopEpoch = N. Daemon commits transaction updating stopEpoch N -> N+1 and journals X. Acknowledgment is lost, and caller loses operation ID X. Caller creates new adminOperationId = Y but still sends expectedStopEpoch = N.",
        "resolution": "Daemon extracts peer UID, computes requestHash for Y, begins transaction, finds no entry in admin_operation_journal for (UID, 'INCREMENT_STOP_EPOCH', Y). Daemon reads global stopEpoch which is now N+1. Compare expectedStopEpoch (N) != currentStopEpoch (N+1). Daemon rolls back and returns ERROR: STALE_EXPECTED_STOP_EPOCH. No state mutation occurs; global stopEpoch remains N+1 and cannot advance to N+2."
      }
    },
    "concurrencyAndCrashSemantics": {
      "A_concurrentIdenticalRetries": "Two simultaneous requests with identical peer UID and adminOperationId. SQLite BEGIN IMMEDIATE serializes them. The first request commits mutation N -> N+1 and writes journal. The second request acquires lock next, hits journal lookup, verifies matching requestHash, and returns cached N+1 result without mutating state.",
      "B_concurrentDifferentOperationsExpectingSameEpoch": "Two different operations (X and Y) with expectedStopEpoch = N arrive concurrently. SQLite BEGIN IMMEDIATE serializes them. First transaction commits N -> N+1. Second transaction proceeds, finds no journal row for its ID, reads current epoch (N+1), detects expectedStopEpoch (N) != current (N+1), and aborts with STALE_EXPECTED_STOP_EPOCH. Epoch advances at most once to N+1.",
      "C_crashBeforeCommit": "If daemon crashes or power fails prior to transaction COMMIT, SQLite rollback occurs on recovery. No stopEpoch mutation, no journal row, and no audit log entry are persisted. System remains at N.",
      "D_crashAfterCommitBeforeAck": "If daemon commits N -> N+1, journal, and audit log, but crashes before sending socket response, WAL guarantees durable persistence of N+1 and journal row. Upon daemon restart, any subsequent retry with operation identity X will find the journal row and return N+1 safely.",
      "E_daemonRestartAuthoritativeness": "All idempotency state and stopEpoch values reside durably in SQLite tables on disk. On restart, authledgerd recovers WAL and uses on-disk tables directly without trusting or maintaining any in-memory state reconstruction."
    },
    "operationResultLookup": {
      "rpcName": "getAdminOperationResult",
      "purpose": "Permits caller to explicitly resolve ambiguous acknowledgment without submitting a mutation request.",
      "parameters": {
        "operationKind": "TEXT (e.g., 'INCREMENT_STOP_EPOCH')",
        "adminOperationId": "TEXT"
      },
      "semantics": "Authenticated via SO_PEERCRED UID. Scoped strictly to authenticatedPeerUid (SELECT ... WHERE authenticated_peer_uid = ? AND operation_kind = ? AND admin_operation_id = ?). Purely read-only, cannot modify stopEpoch, cannot expand permissions. Returns NOT_FOUND if operation was never committed."
    },
    "trustRegistryAndEvidenceImport": {
      "councilEpochRegistry": {
        "storage": "Privileged SQLite table managed exclusively via ADMIN socket.",
        "schema": "council_epochs (epoch_id INTEGER PRIMARY KEY, council_config_hash TEXT NOT NULL, active_from INTEGER, active_to INTEGER, registered_by_uid INTEGER, registered_at INTEGER)",
        "trustAnchorIntegrity": "Trust anchors can only be registered via ADMIN socket by authorized root-allowlisted UIDs. Model-writable CouncilConfig cannot self-establish trust. Silent replacement or rollback is rejected."
      },
      "evidenceImport": {
        "independentRevalidation": "authledgerd parses raw evidence artifacts, re-computes DecisionRecord recordHash, re-evaluates CouncilQuorumProof signatures against registered CouncilConfig public keys, verifies context and repository HEAD bindings, and enforces contemporaneous timestamp ordering. Caller-provided claims and unverified strings are treated as untrusted input."
      }
    },
    "grantIssuanceAndConsumeOnce": {
      "r3AuthorizationGrant": {
        "fieldsBound": [
          "grantId",
          "authorizationEnvelopeHash",
          "decisionRecordHash",
          "candidateHash",
          "decisionRequestId",
          "taskId",
          "contextHash",
          "repositoryHead",
          "allowedScope",
          "prohibitedEffects",
          "stopEpochAtIssuance",
          "authenticatedApproverUid",
          "issuedAt",
          "expiresAt"
        ],
        "validityInvariant": "A grant is strictly void if stopEpochAtIssuance < current_global_stopEpoch."
      },
      "consumeOnceState": {
        "table": "consumed_grants (grant_id TEXT PRIMARY KEY, consumed_by_uid INTEGER NOT NULL, consumed_at INTEGER NOT NULL, transaction_id TEXT NOT NULL)",
        "semantics": "Atomic check-and-insert in SQLite transaction. If grant_id already exists in consumed_grants, fail with GRANT_ALREADY_CONSUMED. On crash before commit, grant remains unconsumed; on crash after commit, grant remains consumed."
      },
      "v1cExitBoundary": {
        "productionConsumers": "ZERO. checkAndConsume / ALLOW_ONCE has zero live production consumers at V1C exit.",
        "componentStatus": {
          "publicationBroker": "Structurally separate daemon; does NOT consume ALLOW_ONCE in V1C.",
          "nightRunner": "Does NOT consume ALLOW_ONCE in V1C.",
          "authorizationLoop": "Does NOT consume ALLOW_ONCE in V1C.",
          "executionGateway": "NOT IMPLEMENTED. V1D future work requiring separate ADR.",
          "authledgerdExternalEffects": "Performs ZERO external side-effects (no git commit/push, no shell execution, no provider CLI calls, no network egress)."
        }
      }
    },
    "yesNoMatrix": {
      "CAN CLAUDE ISSUE AN R3 AUTHORIZATIONGRANT?": "NO",
      "CAN CODEX?": "NO",
      "CAN CLAUDE MODIFY ADMIN UID POLICY?": "NO",
      "CAN CODEX?": "NO",
      "CAN CALLER-SUPPLIED UID BECOME AUTHORITATIVE?": "NO",
      "CAN THE CLIENT SOCKET REGISTER COUNCIL TRUST?": "NO",
      "CAN A MODEL-WRITABLE COUNCILCONFIG SELF-ESTABLISH TRUST?": "NO",
      "CAN CLAUDE INCREMENT STOPEPOCH?": "NO",
      "CAN CODEX?": "NO",
      "CAN THE NORMAL ADMIN API DECREMENT OR RESET STOPEPOCH?": "NO",
      "CAN A LOST ACK PLUS THE SAME OPERATION ID INCREMENT TWICE?": "NO",
      "CAN A LOST ACK PLUS A NEW OPERATION ID WITH A STALE EXPECTED EPOCH INCREMENT TWICE?": "NO",
      "CAN IDEMPOTENCY-KEY REUSE WITH DIFFERENT REQUEST CONTENT SUCCEED?": "NO",
      "CAN POLICY_SATISFIED CAUSE AN EFFECT?": "NO",
      "CAN ALLOW_ONCE CAUSE AN EFFECT DURING V1C?": "NO",
      "CAN BROKER/NIGHT RUNNER/AUTHORIZATION LOOP CONSUME PRODUCTION ALLOW_ONCE?": "NO",
      "DOES V1C IMPLEMENT AN EXECUTION GATEWAY?": "NO"
    }
  }
}
